mapper.sql:
FROM com_project_contract_relation r JOIN com_contract c ON c.tenant_id = r.tenant_id AND c.id = r.contract_id AND c.deleted = 0 WHERE r.tenant_id = #{query.tenantId} AND r.project_id = #{query.projectId} AND r.deleted = 0
AND c.company_code IN #{code}
AND 1 = 0

mapper.select:
SELECT *
FROM com_project_contract_relation
WHERE tenant_id = #{query.tenantId}
  AND project_id = #{query.projectId}
  AND contract_id = #{query.contractId}
  AND relation_role = #{query.relationRole}
  AND deleted = 0
FOR UPDATE
